mapper.select:
SELECT PRD_TRD_METHOD_CD
FROM PRODUCT
WHERE PRD_SN = #{productId}

SELECT t.SVC_REQ_SN AS serviceRequestId, t.TRD_SN AS tradeId, t.QUT_SN AS quoteId, t.TRD_STATUS_CD AS tradeStatusCode, tradeStatus.CMM_NM AS tradeStatusName, SUM(CASE WHEN dispute.TRD_DSP_STATUS_CD IN ('TRDC0016', 'TRDC0017') THEN 1 ELSE 0 END) AS activeDisputeCount, SUM(CASE WHEN dispute.TRD_DSP_STATUS_CD IS NOT NULL AND dispute.TRD_DSP_STATUS_CD NOT IN ('TRDC0016', 'TRDC0017', 'TRDC0018', 'TRDC0019') THEN 1 ELSE 0 END) AS unsupportedDisputeCount, MAX(CASE WHEN dispute.TRD_DSP_STATUS_CD IN ('TRDC0016', 'TRDC0017') THEN dispute.TRD_DSP_SN END) AS activeDisputeId, MAX(CASE WHEN dispute.TRD_DSP_STATUS_CD IN ('TRDC0016', 'TRDC0017') THEN dispute.TRD_DSP_STATUS_CD END) AS activeDisputeStatusCode, MAX(CASE WHEN dispute.TRD_DSP_STATUS_CD IN ('TRDC0016', 'TRDC0017') THEN disputeStatus.CMM_NM END) AS activeDisputeStatusName FROM TRADE t LEFT JOIN CMM_CODE tradeStatus ON tradeStatus.CMM_CD = t.TRD_STATUS_CD LEFT JOIN TRADE_DISPUTE dispute ON dispute.TRD_SN = t.TRD_SN LEFT JOIN CMM_CODE disputeStatus ON disputeStatus.CMM_CD = dispute.TRD_DSP_STATUS_CD WHERE t.TRD_TYPE_CD = 'TRDC0002' AND t.SVC_REQ_SN IN
#{serviceRequestId}
GROUP BY t.SVC_REQ_SN, t.TRD_SN, t.QUT_SN, t.TRD_STATUS_CD, tradeStatus.CMM_NM

