mapper.select:
SELECT t.TRD_SN AS tradeId, CASE WHEN t.BYPR_USR_SN = #{userId} THEN 'BUYER' ELSE 'SELLER' END AS userRole, p.PRD_NM AS productName, productImage.productImageUrl AS productImageUrl, CASE WHEN t.BYPR_USR_SN = #{userId} THEN t.SLLR_USR_SN ELSE t.BYPR_USR_SN END AS counterpartUserId, CASE WHEN t.BYPR_USR_SN = #{userId} THEN seller.USR_NM ELSE buyer.USR_NM END AS counterpartNickname, t.TRD_AMT AS tradeAmount, t.TRD_REG_DT AS createdAt, completedHist.completedAt AS completedAt, CASE WHEN t.TRD_METHOD_CD = 'TRDC0010' AND t.TRD_STATUS_CD = 'TRDC0003' AND o.TRD_OFL_DT IS NOT NULL AND o.TRD_OFL_PLC_NM IS NOT NULL AND TRIM(o.TRD_OFL_PLC_NM) <> '' THEN 'TRDC0004' ELSE t.TRD_STATUS_CD END AS tradeStatus, o.TRD_OFL_DT AS meetingDateTime, o.TRD_OFL_PLC_NM AS meetingPlace, CASE t.TRD_METHOD_CD WHEN 'TRDC0009' THEN 'DELIVERY' WHEN 'TRDC0010' THEN 'OFFLINE' END AS tradeMethod FROM TRADE t JOIN PRODUCT p ON p.PRD_SN = t.PRD_SN JOIN USERS seller ON seller.USR_SN = t.SLLR_USR_SN JOIN USERS buyer ON buyer.USR_SN = t.BYPR_USR_SN LEFT JOIN ( SELECT pi.PRD_SN, f.FL_PATH AS productImageUrl FROM PRODUCT_IMAGE pi JOIN FILES f ON f.FL_SN = pi.FL_SN AND f.FL_USE_YN = 'Y' JOIN ( SELECT PRD_SN, MIN(CASE WHEN PRD_IMG_RPRS_YN = 'Y' THEN 0 ELSE 1 END * 100000 + PRD_IMG_SORT_NO) AS sortKey FROM PRODUCT_IMAGE GROUP BY PRD_SN ) picked ON picked.PRD_SN = pi.PRD_SN AND picked.sortKey = CASE WHEN pi.PRD_IMG_RPRS_YN = 'Y' THEN 0 ELSE 1 END * 100000 + pi.PRD_IMG_SORT_NO ) productImage ON productImage.PRD_SN = p.PRD_SN LEFT JOIN TRADE_OFFLINE o ON o.TRD_SN = t.TRD_SN
LEFT JOIN ( SELECT TRD_SN, MAX(TRD_STS_HST_REG_DT) AS completedAt FROM TRADE_STATUS_HIST WHERE TRD_STS_HST_STATUS_CD = 'TRDC0006' GROUP BY TRD_SN ) completedHist ON completedHist.TRD_SN = t.TRD_SN WHERE t.TRD_TYPE_CD = 'TRDC0001' AND (t.SLLR_USR_SN = #{userId} OR t.BYPR_USR_SN = #{userId})
AND t.BYPR_USR_SN = #{userId}
AND t.SLLR_USR_SN = #{userId}
AND ( CASE WHEN t.TRD_METHOD_CD = 'TRDC0010' AND t.TRD_STATUS_CD = 'TRDC0003' AND o.TRD_OFL_DT IS NOT NULL AND o.TRD_OFL_PLC_NM IS NOT NULL AND TRIM(o.TRD_OFL_PLC_NM) <> '' THEN 'TRDC0004' ELSE t.TRD_STATUS_CD END ) = #{statusCode}
AND ( LOWER(p.PRD_NM) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER( CASE WHEN t.BYPR_USR_SN = #{userId} THEN seller.USR_NM ELSE buyer.USR_NM END ) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR CAST(t.TRD_SN AS CHAR) LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY t.TRD_REG_DT DESC, t.TRD_SN DESC

