mapper.select:
SELECT t.TRD_SN AS tradeId, t.SVC_REQ_SN AS serviceRequestId, CASE WHEN t.REQ_USR_SN = #{userId} THEN 'REQUESTER' ELSE 'PROVIDER' END AS viewerRole, t.TRD_STATUS_CD AS tradeStatusCode, tradeStatus.CMM_NM AS tradeStatusName, t.TRD_AMT AS tradeAmount, sr.SVC_REQ_TTL AS serviceRequestTitle, q.QUT_CN AS quoteSummary, CASE WHEN t.REQ_USR_SN = #{userId} THEN t.PRV_USR_SN ELSE t.REQ_USR_SN END AS counterpartUserId, CASE WHEN t.REQ_USR_SN = #{userId} THEN provider.USR_NM ELSE requester.USR_NM END AS counterpartNickname, t.TRD_AUTO_CMPL_DT AS autoCompleteAt, t.TRD_REG_DT AS createdAt, EXISTS ( SELECT 1 FROM TRADE_DISPUTE dispute WHERE dispute.TRD_SN = t.TRD_SN AND dispute.TRD_DSP_STATUS_CD IN ('TRDC0016', 'TRDC0017') ) AS hasActiveDispute FROM TRADE t JOIN SERVICE_REQUEST sr ON sr.SVC_REQ_SN = t.SVC_REQ_SN JOIN QUOTE q ON q.QUT_SN = t.QUT_SN JOIN USERS requester ON requester.USR_SN = t.REQ_USR_SN JOIN USERS provider ON provider.USR_SN = t.PRV_USR_SN JOIN CMM_CODE tradeStatus ON tradeStatus.CMM_CD = t.TRD_STATUS_CD AND tradeStatus.CMM_USE_YN = 'Y' WHERE t.TRD_TYPE_CD = 'TRDC0002' AND (t.REQ_USR_SN = #{userId} OR t.PRV_USR_SN = #{userId})
AND t.REQ_USR_SN = #{userId}
AND t.PRV_USR_SN = #{userId}
AND t.TRD_STATUS_CD = #{statusCode}
AND ( sr.SVC_REQ_TTL LIKE CONCAT('%', #{keyword}, '%') OR CASE WHEN t.REQ_USR_SN = #{userId} THEN provider.USR_NM ELSE requester.USR_NM END LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY t.TRD_REG_DT DESC, t.TRD_SN DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM TRADE t JOIN SERVICE_REQUEST sr ON sr.SVC_REQ_SN = t.SVC_REQ_SN JOIN QUOTE q ON q.QUT_SN = t.QUT_SN JOIN USERS requester ON requester.USR_SN = t.REQ_USR_SN JOIN USERS provider ON provider.USR_SN = t.PRV_USR_SN JOIN CMM_CODE tradeStatus ON tradeStatus.CMM_CD = t.TRD_STATUS_CD AND tradeStatus.CMM_USE_YN = 'Y' WHERE t.TRD_TYPE_CD = 'TRDC0002' AND (t.REQ_USR_SN = #{userId} OR t.PRV_USR_SN = #{userId})
AND t.REQ_USR_SN = #{userId}
AND t.PRV_USR_SN = #{userId}
AND t.TRD_STATUS_CD = #{statusCode}
AND ( sr.SVC_REQ_TTL LIKE CONCAT('%', #{keyword}, '%') OR CASE WHEN t.REQ_USR_SN = #{userId} THEN provider.USR_NM ELSE requester.USR_NM END LIKE CONCAT('%', #{keyword}, '%') )

